{
  "segment_function": "Examine the Greek concept of action, the agonal spirit, the prepolitical status of legislation and city-building, and the Socratic school's philosophical preference for making (poiēsis) over action (praxis).",
  "claims": [
    {
      "claim": "The Greeks did not count legislating among political activities, treating the lawmaker like a craftsman or architect whose work had to be finished before political activity could begin.",
      "claim_type": "author_position",
      "supporting_excerpt": "An outstanding symptom of this prevailing influence is that the Greeks, in distinction from all later developments, did not count legislating among the political activities. In their opinion, the lawmaker was like the builder of the city wall, someone who had to do and finish his work before political activity could begin.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "Plato and Aristotle turned to legislating and city-building, which were prepolitical to the Greeks, because they wished to turn against politics and action in favor of the greater reliability of making (poiēsis).",
      "claim_type": "author_position",
      "supporting_excerpt": "The Socratic school, on the contrary, turned to these activities, which to the Greeks were prepolitical, because they wished to turn against politics and against action. To them, legislating and the execution of decisions by vote are the most legitimate political activities because in them men “act like craftsmen”: the result of their action is a tangible product, and its process has a clearly recognizable end.",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [],
  "distinctions": [
    {
      "item_a": "Action (praxis)",
      "item_b": "Making (poiēsis)",
      "distinction": "Making involves producing a tangible product with a clearly recognizable end and greater reliability, whereas authentic action possesses an untangible, futile, boundless, and uncertain outcome."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The Greek distinction between the lawmaker as a craftsman and citizens engaging in politeuesthai within the polis.",
    "The Socratic school's reduction of action to making in order to escape the uncertainty and frailty of human affairs."
  ]
}

